INSERT INTO `adoption_pets` VALUES (7,'Mimi',NULL,NULL,NULL,'Mèo Tam Thể đang phục hồi tốt sau khi được chăm sóc.','Mimi được cứu vào một chiều mưa và đang tìm một gia đình thật dịu dàng.','Cần hạt, pate và người nhận nuôi có kinh nghiệm.','available',1,'2026-07-15 03:33:44'),(8,'Mimi 2',NULL,NULL,NULL,'Mèo Tam Thể đã tiêm phòng cơ bản.','Mimi là cô mèo nhỏ nhắn, thích sưởi nắng và rất quấn người.','Cần người chăm sóc lâu dài và vật dụng vệ sinh.','available',1,'2026-07-15 03:33:44'),(9,'Lucy',NULL,NULL,NULL,'Đang theo dõi sức khỏe, ăn uống ổn định.','Một bé mèo hiền, quen sống trong nhà và đang học tin người trở lại.','Cần hỗ trợ chi phí khám định kỳ.','adopted',1,'2026-07-15 03:33:44'),(10,'Nâu',NULL,NULL,NULL,'Đã tẩy giun, đang tăng cân tốt.','Nâu được đón về từ khu chợ nhỏ, ngoan và hợp với gia đình yên tĩnh.','Cần thức ăn mềm và nhà tạm.','adopted',1,'2026-07-15 03:33:44'),(11,'Bông',NULL,NULL,NULL,'Sức khỏe ổn định, còn hơi nhát.','Bông thân thiện, thích được vuốt ve và có thể hòa nhập với mèo khác.','Cần người nhận nuôi kiên nhẫn.','available',1,'2026-07-15 03:33:44'),(12,'Miu',NULL,NULL,NULL,'Đã khám tổng quát, không phát hiện bất thường.','Miu nhỏ người, sạch sẽ, phù hợp căn hộ và người mới nuôi mèo.','Cần cát vệ sinh, hạt kitten và đồ chơi.','adopted',1,'2026-07-15 03:33:44');
