INSERT INTO `doctors` VALUES (1,2,1,'Dr. Nguyen Van A','Bác sĩ thú y đa khoa khám tổng quát.','https://i.pravatar.cc/150?img=11',4.80,'active'),(2,24,1,'Bs. Trần Văn Nhân','Bác sĩ có hơn 20 năm kinh nghiệm trong lĩnh vực phẫu thuật thú y ngoại khoa và điều trị nội khoa chuyên sâu. Tốt nghiệp Thạc sĩ thú y từ Đại học Nông Lâm TP.HCM.','https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400',4.90,'active'),(3,25,2,'Bs. Võ Công Nam','14 năm kinh nghiệm chuyên môn về chẩn đoán hình ảnh (siêu âm, X-quang) và xét nghiệm lâm sàng. Từng tu nghiệp tại Thái Lan về chẩn đoán bệnh lý thú y.','https://images.unsplash.com/photo-1622253692010-333f2da6031d?w=400',4.80,'active'),(4,26,1,'Bs. Nguyễn Thu Hồng','5 năm kinh nghiệm điều trị các bệnh truyền nhiễm, chăm sóc sức khỏe ban đầu, tiêm phòng và tư vấn dinh dưỡng cho thú cưng nhỏ.','https://images.unsplash.com/photo-1594824813573-246434de83fb?w=400',4.70,'active'),(5,27,2,'Bs. Trần Phương Trâm','7 năm kinh nghiệm chuyên về da liễu, chăm sóc nha khoa và phục hồi chức năng sau chấn thương cho chó mèo.','https://images.unsplash.com/photo-1559839734-2b71ea197ec2?w=400',4.80,'active'),(6,28,2,'Dr. Đặng Hoàng Phúc','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=63',4.60,'active'),(7,29,2,'Dr. Trần Hoàng Bình','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=41',4.70,'active'),(8,30,1,'Dr. Nguyễn Minh Dũng','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=0',4.80,'active'),(9,31,1,'Dr. Phan Văn Quỳnh','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=25',4.90,'active'),(10,32,1,'Dr. Võ Văn Bình','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=17',4.70,'active'),(11,33,2,'Dr. Hoàng Văn Sơn','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=29',5.00,'active'),(12,34,2,'Dr. Võ Thành Vinh','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=30',4.50,'active'),(13,35,2,'Dr. Trần Quốc Hương','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=1',4.50,'active'),(14,36,1,'Dr. Lê Anh Thảo','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=59',4.80,'active'),(15,37,2,'Dr. Nguyễn Văn Quỳnh','Bác sĩ thú y chuyên nghiệp tại Dr.Pet\'s House.','https://i.pravatar.cc/150?img=34',4.80,'active');
