INSERT INTO `first_aid_guides` VALUES (1,1,'Sơ cứu khi chó bị hóc dị vật','Khi chó có dấu hiệu nghẹt thở, khó thở hoặc liên tục dùng chân cào vào miệng, rất có thể chúng đang bị hóc dị vật. Đây là tình huống đe dọa tính mạng cần được xử lý bình tĩnh và chính xác ngay lập tức.','0868686868','https://www.youtube.com/watch?v=sample_choking_dog','published',1,'2026-07-14 11:15:25','so-cuu-khi-cho-bi-hoc-di-vat'),(2,2,'Xử lý mèo bị ngộ độc thực phẩm','Mèo rất tò mò và có thể nuốt phải chocolate, hành tỏi, cây độc hoặc hóa chất tẩy rửa trong nhà. Ngộ độc thực phẩm ở mèo có thể tiến triển rất nhanh, cần được sơ cứu đúng cách trước khi đưa tới thú y.','0868686868','https://www.youtube.com/watch?v=sample_poisoned_cat','published',1,'2026-07-14 11:15:25','xu-ly-meo-bi-ngo-doc-thuc-pham'),(3,1,'Sơ cứu vết bỏng chó mèo','Thú cưng có thể bị bỏng do nước sôi, dầu mỡ nóng, bỏng hóa chất hoặc bỏng điện. Sơ cứu vết bỏng nhanh chóng giúp làm giảm tổn thương mô và giảm đau cho bé.','0868686868',NULL,'published',1,'2026-07-14 11:15:25','so-cuu-vet-bong-cho-meo'),(4,4,'Cấp cứu vết thương hở do cắn nhau','Xung đột giữa các bé cún hoặc mèo có thể gây ra những vết rách da, chảy máu nhiều. Sơ cứu tại chỗ giúp cầm máu và làm sạch vết thương tạm thời tránh nhiễm trùng nguy hiểm.','0868686868',NULL,'published',1,'2026-07-14 11:15:25','cap-cuu-vet-thuong-ho-do-can-nhau');
/*!40000 ALTER TABLE `first_aid_guides` ENABLE KEYS */;
UNLOCK TABLES;

