INSERT INTO `first_aid_steps` VALUES (1,1,1,'Mở rộng miệng chó bằng hai tay. Sử dụng đèn pin để quan sát kỹ phần cuống họng. Nếu thấy dị vật ở gần, hãy cố gắng lấy ra bằng tay hoặc nhíp.','https://images.unsplash.com/photo-1587300003388-59208cc962cb?w=800'),(2,1,2,'Với chó nhỏ, hãy giữ chân sau và dốc ngược chúng. Với chó lớn, hãy giữ chúng ở tư thế \'xe cút kít\' (nâng hai chân sau lên cao) để trọng lực giúp dị vật rơi ra.','https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800'),(3,1,3,'Đặt nắm tay ở vùng bụng ngay dưới xương sườn. Thực hiện 5 lần đẩy mạnh và nhanh về phía trước và hướng lên trên để tạo áp lực tống dị vật ra ngoài.','https://images.unsplash.com/photo-1561037404-61cd46aa615b?w=800'),(4,2,1,'Kiểm tra xung quanh xem có vỏ kẹo chocolate, lá cây bị cắn dở hay chai lọ hóa chất bị đổ không để báo chính xác cho bác sĩ.','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800'),(5,2,2,'Nếu mèo nuốt phải axit, chất kiềm mạnh hoặc hóa chất ăn mòn, việc tự ý gây nôn sẽ làm bỏng thực quản nghiêm trọng hơn. Tuyệt đối không gây nôn trừ khi được bác sĩ hướng dẫn.','https://images.unsplash.com/photo-1495360010541-f48722b34f7d?w=800'),(6,2,3,'Giữ ấm cho mèo bằng chăn, mang theo mẫu chất độc (hoặc vỏ chai hóa chất) và đưa ngay tới cơ sở thú y gần nhất.','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=800'),(7,3,1,'Dùng nước sạch xả nhẹ nhàng lên vùng da bị bỏng của thú cưng trong 10-15 phút để hạ nhiệt độ vết bỏng ngay lập tức. Tuyệt đối không dùng đá lạnh áp trực tiếp lên vết thương.','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800'),(8,3,2,'Sử dụng gạc sạch hoặc khăn mềm ẩm che phủ lên vết bỏng một cách nhẹ nhàng. Tránh băng quá chặt làm bít khí và gây đau đớn.','https://images.unsplash.com/photo-1544568100-847a948585b9?w=800'),(9,3,3,'Tuyệt đối không bôi kem đánh răng, mỡ trăn hay dầu ăn lên vết bỏng vì dễ gây bí nhiệt và nhiễm trùng da nghiêm trọng.','https://images.unsplash.com/photo-1530281700549-e82e7bf110d6?w=800'),(10,4,1,'Dùng một miếng gạc hoặc khăn sạch đè chặt lên vết thương hở trong 3-5 phút để máu ngừng chảy. Giữ lực đè ổn định.','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800'),(11,4,2,'Rửa sạch vết thương bằng nước muối sinh lý ấm, loại bỏ cát bụi bẩn. Dùng kéo y tế cắt bớt phần lông xung quanh nếu cần thiết để tránh bám dính.','https://images.unsplash.com/photo-1588943211346-0908a1fb0b01?w=800'),(12,4,3,'Sử dụng băng thun hoặc băng dính y tế cố định gạc sạch để che chắn vết thương khỏi bụi bẩn khi di chuyển đến phòng khám.','https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=800');
/*!40000 ALTER TABLE `first_aid_steps` ENABLE KEYS */;
UNLOCK TABLES;

