DROP TABLE IF EXISTS `pet_reminders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pet_reminders` (
  `reminder_id` bigint NOT NULL AUTO_INCREMENT,
  `pet_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `reminder_type` enum('vaccination','deworming','routine_checkup','other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `remind_date` date NOT NULL,
  `remind_before_days` int NOT NULL DEFAULT '3',
  `note` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `completed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`reminder_id`),
  KEY `idx_reminders_pet_id` (`pet_id`),
  KEY `idx_reminders_user_id` (`user_id`),
  CONSTRAINT `pet_reminders_pet_id_fkey` FOREIGN KEY (`pet_id`) REFERENCES `pets` (`pet_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pet_reminders_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

