INSERT INTO `post_comments` VALUES (1,1,3,NULL,'Bài viết chi tiết quá ạ! Bé mèo nhà em 3 tháng tuổi thì nên tiêm phòng mũi thứ mấy rồi bác sĩ ơi?','visible','2026-07-14 11:15:24'),(2,1,1,1,'Chào bạn, với bé mèo 3 tháng tuổi bạn nên cho bé hoàn thành mũi tiêm vắc-xin 4 trong 1 thứ 2 hoặc thứ 3 nhé. Bạn có thể mang bé qua Dr.Pet\'s House để được khám lâm sàng trước khi tiêm nha!','visible','2026-07-14 11:15:24'),(3,1,38,NULL,'Cảm ơn bác sĩ, thông tin cực kỳ hữu ích cho người mới tập nuôi chó như mình.','visible','2026-07-14 11:15:24'),(4,11,3,NULL,'Cún cưng cưng quá bạn ơi! Địa điểm này ở đâu vậy ạ?','visible','2026-07-14 11:15:24'),(5,11,38,NULL,'Thời tiết dạo này nóng thật, đi chiều mát sau 5h là hợp lý nhất rồi.','visible','2026-07-14 11:15:24'),(6,12,39,NULL,'Bé nhà mình đợt trước cũng vậy, đi khám bác sĩ bảo bị nhiệt miệng đó bạn.','visible','2026-07-14 11:15:24'),(7,12,40,NULL,'Bạn thử đổi sang pate lon xem bé có kích thích ăn hơn không.','visible','2026-07-14 11:15:24'),(8,12,41,NULL,'Nên mang bé đi khám thú y sớm nha bạn, bỏ bữa 3 ngày là khá nguy hiểm đấy.','visible','2026-07-14 11:15:24'),(9,13,3,NULL,'Máy lọc không khí hãng nào tốt cho lông pet hả bạn?','visible','2026-07-14 11:15:24'),(10,13,38,NULL,'Dùng tinh dầu sả chanh được không bạn ơi? Có sợ ảnh hưởng đường hô hấp của bé không?','visible','2026-07-14 11:15:25'),(11,14,42,NULL,'Do cún ăn nhanh nuốt nhiều khí đó bạn, mua bát ăn chậm hoặc chia nhỏ bữa ăn ra thử xem.','visible','2026-07-14 11:15:25'),(12,14,43,NULL,'Trộm vía cún con hay bị nấc vậy á, lớn tí là hết hà, đừng lo quá bạn.','visible','2026-07-14 11:15:25'),(13,15,39,NULL,'Trời đất, ngủ kiểu gì vẹo cả cổ thế kia ? boss nhà bạn hài hước quá.','visible','2026-07-14 11:15:25'),(14,15,40,NULL,'Dễ thương xỉu luôn á! Xin vía ngủ ngon nha Miu.','visible','2026-07-14 11:15:25'),(15,16,3,NULL,'Đúng rồi bạn ơi, tiền chữa sỏi thận bằng mấy lần tiền mua hạt xịn luôn.','visible','2026-07-14 11:15:25'),(16,16,38,NULL,'Chuẩn luôn, nên chọn các thương hiệu uy tín như Royal Canin hoặc Catsrang.','visible','2026-07-14 11:15:25'),(17,16,41,NULL,'Bài viết rất hữu ích cho các bạn mới nuôi mèo!','visible','2026-07-14 11:15:25'),(18,17,39,NULL,'Mình cũng đang tập cho bé nhà mình, áp dụng thử cách của bạn xem sao.','visible','2026-07-14 11:15:25'),(19,17,40,NULL,'Mẹo nhỏ là có thể dùng tã thấm nước tiểu của bé đặt sẵn vào khay nha.','visible','2026-07-14 11:15:25'),(20,17,42,NULL,'Cho mình hỏi mua snack Bowwow ở đâu chính hãng rẻ vậy bạn?','visible','2026-07-14 11:15:25'),(21,18,38,NULL,'Máy sấy này mua khoảng bao nhiêu tiền vậy bạn?','visible','2026-07-14 11:15:25'),(22,18,43,NULL,'Lông mèo sấy bằng máy này có bị khô xơ không bạn nhỉ?','visible','2026-07-14 11:15:25'),(23,19,3,NULL,'Cún nhà mình bị viêm tai suốt, chữa mãi không dứt điểm, buồn ghê.','visible','2026-07-14 11:15:25'),(24,19,39,NULL,'Bạn phải sấy thật khô tai sau khi tắm nữa nha, ẩm ướt là nấm mốc lên ngay.','visible','2026-07-14 11:15:25');
