INSERT INTO `posts` VALUES (1,1,1,'official_blog','Cẩm nang chăm sóc chó mèo toàn tập cho người mới bắt đầu','cam-nang-cham-soc-cho-meo-toan-tap-cho-nguoi-moi-bat-dau','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800','<h2>1. Chuẩn bị không gian sống và vật dụng cần thiết</h2>\n<p>Khi đón một chú chó hoặc mèo về nhà, việc chuẩn bị không gian an toàn và sạch sẽ là vô cùng quan trọng. Bạn cần chuẩn bị sẵn:</p>\n<ul>\n  <li>Khay ăn, chén nước (nên chọn chất liệu inox hoặc sứ).</li>\n  <li>Nệm nằm, chuồng hoặc rào quây.</li>\n  <li>Dụng cụ vệ sinh: khay cát (cho mèo), tã lót đi vệ sinh (cho chó).</li>\n  <li>Đồ chơi gặm nhấm, cào móng giúp giảm stress.</li>\n</ul>\n\n<h2>2. Chế độ dinh dưỡng hợp lý</h2>\n<p>Dinh dưỡng đóng vai trò quyết định đến sự phát triển của thú cưng. Mèo là động vật ăn thịt bắt buộc, cần nhiều đạm động vật và taurine. Ngược lại, chó là động vật ăn tạp thiên thịt, cần chế độ ăn cân đối giữa protein, tinh bột, chất xơ và chất béo.</p>\n<ul>\n  <li><strong>Dưới 2 tháng tuổi:</strong> Chủ yếu uống sữa mẹ hoặc sữa công thức chuyên dụng.</li>\n  <li><strong>Từ 2 - 6 tháng tuổi:</strong> Ăn cháo loãng, hạt ngâm mềm hoặc pate ăn dặm, chia làm 3-4 bữa nhỏ/ngày.</li>\n  <li><strong>Trên 6 tháng tuổi:</strong> Có thể ăn hạt khô hoàn toàn hoặc tự nấu thức ăn (không nêm gia vị), chia làm 2 bữa/ngày.</li>\n</ul>\n\n<h2>3. Vắc-xin và chăm sóc y tế định kỳ</h2>\n<p>Đừng quên lịch tiêm phòng và tẩy giun. Đây là rào chắn bảo vệ thú cưng khỏi các bệnh truyền nhiễm nguy hiểm như Parvo, Care ở chó hay giảm bạch cầu ở mèo.</p>\n<p>Hãy mang bé đến phòng khám thú y uy tín như Dr.Pet\'s House để được tư vấn phác đồ tiêm chủng chuẩn xác nhất nhé!</p>','published',2450,'2026-07-14 11:15:24','2026-07-15 03:33:43','Bạn mới nuôi thú cưng và chưa biết bắt đầu từ đâu? Xem ngay cẩm nang chi tiết từ các chuyên gia dinh dưỡng và sức khỏe tại Dr.Pet\'s House để chuẩn bị tốt nhất cho người bạn bốn chân.',1,'CHAMSOCPET,KIENTHUCTHUCUNG',1250),(2,2,1,'official_blog','Chế độ dinh dưỡng hoàn hảo cho mèo Anh Lông Ngắn dưới 1 tuổi','che-do-dinh-duong-hoan-hao-cho-meo-anh-long-ngan-duoi-1-tuoi','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800','<p>Mèo Anh Lông Ngắn (Aln) là giống mèo rất được ưa chuộng nhờ ngoại hình mập mạp và tính cách hiền lành. Giai đoạn dưới 1 tuổi là thời điểm mèo Aln tăng trưởng nhanh nhất, đặc biệt là hệ cơ và xương...</p>','published',1550,'2026-07-14 11:15:24','2026-07-15 03:33:43','Mèo Anh Lông Ngắn con cần chế độ dinh dưỡng thế nào để phát triển khung xương vững chắc và bộ lông dày mượt? Hãy cùng tìm hiểu công thức thức ăn tối ưu từ chuyên gia.',0,'DINHDUONGMEO,MEOALN',520),(3,1,1,'official_blog','Làm thế nào để trị dứt điểm ve rận cho cún yêu tại nhà?','lam-the-nao-de-tri-dut-diem-ve-ran-cho-cun-yeu-tai-nha','https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800','<p>Ve rận luôn là nỗi ám ảnh của những người nuôi chó. Chúng sinh sôi rất nhanh và có thể sống ẩn nấp trong kẽ tường, thảm nhà...</p>','published',1220,'2026-07-14 11:15:24','2026-07-15 03:33:43','Ve rận không chỉ gây ngứa ngáy mà còn truyền nhiễm các bệnh nguy hiểm về máu cho chó. Xem ngay các bước trị ve rận tận gốc và phòng ngừa hiệu quả tại nhà.',0,'SUCKHOEDOG,TRIVERAN',340),(4,3,1,'official_blog','Giải mã ngôn ngữ cơ thể của mèo: Mèo đang muốn nói gì?','giai-ma-ngon-ngu-co-the-cua-meo-meo-dang-muon-noi-gi','https://images.unsplash.com/photo-1495360010541-f48722b34f7d?w=800','<p>Mèo là loài động vật tinh tế và có phần bí ẩn. Đôi khi bạn không hiểu tại sao chúng lại vẫy đuôi liên tục hay cụp tai xuống...</p>','published',980,'2026-07-14 11:15:24','2026-07-15 03:33:43','Mèo giao tiếp chủ yếu qua đuôi, tai và cử chỉ cơ thể. Học cách đọc vị các hành động này sẽ giúp bạn hiểu rõ tâm trạng và gắn kết hơn với chú mèo của mình.',0,'TAMLYMEO,NGONNGUMEOT',890),(5,4,1,'official_blog','Quy trình tắm và vệ sinh tai cho chó Poodle sạch thơm như spa','quy-trinh-tam-va-ve-sinh-tai-cho-cho-poodle-sach-thom-nhu-spa','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800','<p>Với bộ lông xoăn và cấu trúc tai cụp kín, Poodle cần một chế độ vệ sinh kỹ lưỡng hơn nhiều giống chó khác...</p>','published',750,'2026-07-14 11:15:24','2026-07-15 03:33:43','Chó Poodle có bộ lông xoăn đặc thù rất dễ bị rối và bám bẩn. Hướng dẫn chi tiết quy trình tắm, sấy và vệ sinh tai tại nhà chuẩn spa giúp cún cưng luôn thơm tho.',0,'GROOMING,POODLE',450),(6,4,72,'community','Kinh nghiệm chọn cát vệ sinh khử mùi tốt cho mèo chung cư','kinh-nghiem-chon-cat-ve-sinh-khu-mui-tot-cho-meo-chung-cu','https://images.unsplash.com/photo-1574158622682-e40e69881006?w=800','<p>Khi nuôi mèo ở các căn hộ chung cư có diện tích giới hạn, việc giữ gìn vệ sinh và khử mùi khay cát là yếu tố ưu tiên hàng đầu...</p>','published',420,'2026-07-14 11:15:24','2026-07-15 03:33:43','Sống tại chung cư không gian kín dễ bị tích tụ mùi hôi từ khay cát. Dưới đây là review chi tiết các loại cát vệ sinh đất sét, cát đậu nành tốt nhất.',0,'MEOVAT,MEOCHUNGCU',217),(7,1,1,'official_blog','Có nên triệt sản cho chó đực? Lợi ích và những lưu ý quan trọng','co-nen-triet-san-cho-cho-duc-loi-ich-va-nhung-luu-y-quan-trong','https://images.unsplash.com/photo-1544568100-847a948585b9?w=800','<p>Nhiều chủ nuôi ngần ngại triệt sản cho cún đực vì sợ ảnh hưởng tính cách của bé. Tuy nhiên dưới góc độ y khoa...</p>','published',310,'2026-07-14 11:15:24','2026-07-15 03:33:43','Triệt sản chó đực giúp hạn chế tính trạng đi tiểu đánh dấu lãnh thổ, giảm kích động và ngăn ngừa một số bệnh ung thư. Hãy cùng xem lời khuyên từ bác sĩ.',0,'TRIETSAN,SUCKHOEDOG',180),(8,1,73,'community','Chia sẻ nhật ký chữa trị bệnh giảm bạch cầu (FPV) thành công cho bé mèo Mun','chia-se-nhat-ky-chua-tri-benh-giam-bach-cau-fpv-thanh-cong-cho-be-meo-mun','https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=800','<p>Chào mọi người, tuần trước bé Mun nhà mình bỗng dưng bỏ ăn, nôn trớ liên tục rồi tiêu chảy cấp. Đi test nhanh thì dương tính với FPV...</p>','published',530,'2026-07-14 11:15:24','2026-07-15 03:33:43','Giảm bạch cầu là căn bệnh nguy hiểm với tỷ lệ tử vong cao ở mèo con. Mình xin chia sẻ hành trình điều trị tích cực giúp bé Mun vượt qua tử thần.',0,'FPV,SUCKHOEMEO',1050),(9,2,1,'official_blog','Top 5 loại pate dinh dưỡng giàu protein cho mèo kén ăn','top-5-loai-pate-dinh-duong-giau-protein-cho-meo-ken-an','https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=800','<p>Mèo kén ăn là vấn đề khiến nhiều Sen đau đầu. Giải pháp tốt nhất là bổ sung pate dinh dưỡng vừa kích thích ăn ngon vừa cấp nước...</p>','published',220,'2026-07-14 11:15:24','2026-07-15 03:33:43','Mèo lười uống nước và chán hạt khô? Đừng bỏ qua danh sách 5 loại pate thơm ngon, giàu độ ẩm và protein kích thích vị giác của những bé mèo khó tính nhất.',0,'PATEMEO,DINHDUONG',280),(10,3,1,'official_blog','Cách xử lý tâm lý khi chó cưng tỏ ra lo lắng, sợ hãi tiếng sấm sét','cach-xu-ly-tam-ly-khi-cho-cung-to-ra-lo-an-so-hai-tieng-sam-set','https://images.unsplash.com/photo-1530281700549-e82e7bf110d6?w=800','<p>Hội chứng sợ tiếng động lớn (sấm sét, pháo hoa) rất phổ biến ở chó cưng. Điều này xuất phát từ thính giác nhạy cảm gấp nhiều lần con người...</p>','published',140,'2026-07-14 11:15:24','2026-07-15 03:33:43','Nhiều chú chó hoảng loạn, cào cấu hoặc bỏ trốn khi trời mưa giông sấm sét. Tìm hiểu phương pháp xoa dịu nỗi sợ hãi tiếng động lớn cho cún cưng.',0,'TAMLYDOG,SAMSET',390),(11,1,1,'community','Cuối tuần dạo chơi cùng bé Cún','cuoi-tuan-dao-choi-cung-be-cun','https://images.unsplash.com/photo-1544568100-847a948585b9?w=800','Thời tiết đẹp quá mọi người ạ! Nhớ mang theo nước uống đầy đủ cho các bé khi ra ngoài nhé. ?☀️ Dr.Pet’s House gợi ý nên đi dạo sau 5h chiều để tránh nắng nóng ảnh hưởng đến bàn chân của bé.','published',3200,'2026-07-14 11:15:24','2026-07-15 03:33:43','Thời tiết đẹp quá mọi người ạ! Nhớ mang theo nước uống đầy đủ cho các bé khi ra ngoài nhé. ?☀️',0,'DAOPHO,CUNCUNG,CUOITUAN',1200),(12,3,72,'community','Mèo biếng ăn phải làm sao?','meo-bieng-an-phai-lam-sao','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800','Bé mèo nhà mình (giống Anh lông ngắn, 2 tuổi) 3 ngày nay tự nhiên ăn rất ít, bỏ bữa sáng. Bé vẫn chơi đùa bình thường nhưng lười vận động hơn... Có Sen nào từng gặp tình trạng này chưa, cho mình xin ít kinh nghiệm với ạ!','published',512,'2026-07-14 11:15:24','2026-07-15 03:33:43','Bé mèo nhà mình (giống Anh lông ngắn, 2 tuổi) 3 ngày nay tự nhiên ăn rất ít, bỏ bữa sáng. Bé vẫn chơi đùa bình thường nhưng lười vận động hơn...',0,'MEOBIENGAN,SUCKHOETHUCUNG',217),(13,4,73,'community','Cách giữ nhà luôn thơm tho khi nuôi thú cưng','cach-giu-nha-luon-thom-tho-khi-nuoi-thu-cung','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800','Nhà mình nuôi 2 bé cún nên mùi khá là nồng. Sau một thời gian tìm hiểu mình phát hiện ra dùng máy lọc không khí kết hợp với tinh dầu tự nhiên (loại an toàn cho pet) cực kỳ hiệu quả luôn!','published',1800,'2026-07-14 11:15:24','2026-07-15 03:33:43','Nhà mình nuôi 2 bé cún nên mùi khá là nồng. Sau một thời gian tìm hiểu mình phát hiện ra dùng máy lọc không khí kết hợp với tinh dầu tự nhiên cực kỳ hiệu quả luôn!',0,'MEOVAT,THOMNHASACHCUA',1000),(14,1,72,'community','Cún con bị nấc cụt sau khi ăn có sao không?','cun-con-bi-nac-cut-sau-khi-an-co-sao-khong','https://images.unsplash.com/photo-1530281700549-e82e7bf110d6?w=800','Bé Poodle nhà mình 3 tháng tuổi, cứ ăn xong là bị nấc cụt tầm 5-10 phút. Có bác nào gặp tình trạng này chưa ạ? Có cần phải đưa đi bác sĩ không hay là do bé ăn quá nhanh?','published',190,'2026-07-14 11:15:24','2026-07-15 03:33:43','Bé Poodle nhà mình 3 tháng tuổi, cứ ăn xong là bị nấc cụt tầm 5-10 phút. Có bác nào gặp tình trạng này chưa ạ? Có cần phải đưa đi bác sĩ không?',0,'HOIDAP,SUCKHOECUN',62),(15,3,73,'community','Góc ngủ bá đạo của bé Miu nhà em','goc-ngu-ba-dao-cua-be-miu-nha-em','https://images.unsplash.com/photo-1573865526739-10659fec78a5?w=800','Góc ngủ bá đạo của bé Miu nhà em. Mọi người có ảnh dìm hàng boss không ạ? Khoe dưới bình luận đi nào cả nhà ơi!','published',240,'2026-07-14 11:15:24','2026-07-15 03:33:43','Góc ngủ bá đạo của bé Miu nhà em. Mọi người có ảnh dìm hàng boss không ạ?',0,'MEOCUNG,ANHDIM',89),(16,2,73,'community','Có nên cho mèo ăn thức ăn hạt giá rẻ không?','co-nen-cho-meo-an-thuc-an-hat-gia-re-khong','https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=800','Mình thấy nhiều bạn nuôi mèo sinh viên hay mua mấy loại hạt giá rẻ không rõ nguồn gốc. Mèo ăn lâu ngày rất dễ bị sỏi tiết niệu và suy thận. Mọi người nên đầu tư hạt chất lượng một chút, hoặc tự làm thức ăn ướt trộn thêm sẽ tốt hơn nhiều đó ạ!','published',1420,'2026-07-14 11:15:24','2026-07-15 03:33:43','Nhiều loại hạt giá rẻ chứa quá nhiều chất độn bột ngô, bột sắn dễ gây sỏi thận cho mèo. Hãy cùng chia sẻ kinh nghiệm lựa chọn hạt chất lượng và tiết kiệm.',0,'DINHDUONGMEO,HATCHOMEO',750),(17,3,72,'community','Hành trình huấn luyện cún đi vệ sinh đúng chỗ trong 2 tuần','hanh-trinh-huan-luyen-cun-di-ve-sinh-dung-cho-trong-2-tuan','https://images.unsplash.com/photo-1543466835-00a7907e9de1?w=800','Tuần đầu tiên mình dùng xịt xi tiểu của Dr.Pet\'s House xịt vào khay vệ sinh, cứ thấy bé đi vòng quanh ngửi ngửi là bế ngay vào khay. Khi bé đi đúng thì thưởng ngay Snack Bowwow và xoa đầu khen ngợi. Đến tuần thứ 2 bé đã tự động chạy vào khay khi buồn đi vệ sinh rồi!','published',2100,'2026-07-14 11:15:24','2026-07-15 03:33:43','Kiên trì áp dụng phương pháp dùng xịt hướng dẫn vệ sinh kết hợp khen thưởng bằng bánh thưởng. Chia sẻ chi tiết lịch trình hằng ngày cho các Sen.',0,'HUANLUYENCUN,MEOVAT',950),(18,4,73,'community','Review máy sấy lông thú cưng 3 trong 1 tại nhà','review-may-say-long-thu-cung-3-trong-1-tai-nha','https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=800','Em máy sấy này sức gió siêu mạnh luôn mọi người ơi, sấy bé Samoyed lông dày cộp mà chỉ mất tầm 25 phút là khô ráo hoàn toàn. Máy có chế độ sấy ấm và sấy mát điều chỉnh rất linh hoạt, tiếng ồn ở mức chấp nhận được chứ không làm cún hoảng sợ.','published',820,'2026-07-14 11:15:24','2026-07-15 03:33:43','Tự tắm cho bé tại nhà rất vui nhưng khâu sấy lông luôn là ác mộng. Mình mới tậu em máy sấy chuyên dụng Chunzhou 2800W và đây là đánh giá chi tiết.',0,'GROOMING,VESINH',410),(19,1,72,'community','Dấu hiệu nhận biết sớm bệnh viêm tai ở chó tai cụp','dau-hieu-nhan-biet-som-benh-viem-tai-o-cho-tai-cup','https://images.unsplash.com/photo-1588943211346-0908a1fb0b01?w=800','Mọi người nuôi Poodle nhớ nhổ lông tai định kỳ và dùng nước rửa tai chuyên dụng 1-2 lần/tuần nhé. Nếu thấy bé gãi tai liên tục, lắc đầu thường xuyên hoặc khi ngửi tai thấy có mùi hôi hắc thì 90% là bé bị viêm tai rồi, cần đưa đi bác sĩ thú y ngay.','published',1150,'2026-07-14 11:15:24','2026-07-15 03:33:43','Các giống chó tai cụp như Poodle, Cocker rất dễ bị viêm tai giữa nếu không vệ sinh tai đúng cách. Hãy chú ý các biểu hiện gãi tai liên tục, tai có mùi hôi.',0,'SUCKHOEDOG,TAICUP',680),(20,3,73,'community','Mèo con kêu liên tục vào ban đêm: Nguyên nhân và cách khắc phục','meo-con-keu-lien-tuc-vao-ban-dem-nguyen-nhan-va-cach-khac-phuc','https://images.unsplash.com/photo-1526336024174-e58f5cdd8e13?w=800','Các Sen có thể để một chiếc áo cũ của mình vào ổ nằm của bé để bé quen mùi chủ, hoặc đặt một chiếc đồng hồ tích tắc nhỏ gần đó giả lập tiếng nhịp tim của mèo mẹ. Ban ngày nhớ chơi với bé nhiều hơn để ban đêm bé mệt và ngủ say nhé!','published',980,'2026-07-14 11:15:24','2026-07-15 03:33:43','Mèo con mới về nhà thường khóc đêm vì nhớ mẹ và môi trường lạ. Làm thế nào để xoa dịu giúp bé và gia đình có giấc ngủ ngon?',0,'TAMLYMEO,MEOCON',530),(21,4,72,'community','Lựa chọn sữa tắm cho cún cưng có làn da nhạy cảm','lua-chon-sua-tam-cho-cun-cung-co-lan-da-nhay-cam','https://images.unsplash.com/photo-1517849845537-4d257902454a?w=800','Khuyên thật lòng các bạn nuôi Bulldog hay Pug da nhạy cảm nên dùng sữa tắm có chiết xuất yến mạch hoặc trà xanh thiên nhiên (như Tropiclean Berry & Coconut). Hạn chế dùng các loại có mùi quá nồng vì rất dễ gây kích ứng da pet.','published',670,'2026-07-14 11:15:24','2026-07-15 03:33:43','Cún nhà mình thuộc dòng Bulldog da nhạy cảm và rất dễ bị dị ứng, nổi mẩn đỏ. Mình đã test qua 5 loại sữa tắm khác nhau và tìm ra chân ái.',0,'GROOMING,BULLDOG,SKINCARE',320),(22,2,72,'community','Bổ sung Gel dinh dưỡng cho thú cưng sau khi ốm dậy','bo-sung-gel-dinh-duong-cho-thu-cung-sau-khi-om-day','https://images.unsplash.com/photo-1544568100-847a948585b9?w=800','Gel dinh dưỡng rất tốt cho các bé suy nhược, bỏ ăn hoặc sau phẫu thuật. Mình cho bé ăn trực tiếp hoặc trộn vào cháo/hạt ngâm ấm. Chỉ sau 1 tuần bé đã lấy lại được năng lượng và ham chạy nhảy trở lại rồi, trộm vía rất thích mùi vị của loại gel này.','published',890,'2026-07-14 11:15:24','2026-07-15 03:33:43','Bé cún nhà mình vừa trải qua đợt điều trị viêm ruột, người gầy rộc đi. Bác sĩ khuyên bổ sung Gel dinh dưỡng Nutri-plus để phục hồi thể trạng nhanh chóng.',0,'SUCKHOEPET,GELDINHINGUONG',480);
