INSERT INTO `products` VALUES (1,1,'Dầu cá cho mèo WILD CAUGHT Omega-3 Fish Oil For Cats','Dầu cá cho mèo WILD CAUGHT Omega-3 Fish Oil For Cats là sản phẩm bổ sung omega-3 dạng lỏng dành cho mèo, hỗ trợ chăm sóc da, lông và sức khỏe tổng thể. Sản phẩm được chiết xuất từ nguồn dầu cá tự nhiên của các loài cá biển như anchovies, herring, mackerel và sardines được đánh bắt từ vùng biển lạnh, sạch gần Iceland. Thiết kế vòi pump tiện lợi giúp định lượng dễ dàng khi sử dụng mỗi ngày. Phù hợp cho nhiều giống mèo, từ mèo con đến mèo trưởng thành.\nLợi ích chính\nSản phẩm cung cấp nguồn omega-3 ...',283000.00,65,4.80,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',343000.00,16,'all'),(2,1,'Thức ăn cho chó con vị cá hồi JIREHO Salmon Puppy','Thức ăn cho chó con vị cá hồi JIREHO Salmon Puppy là giải pháp dinh dưỡng toàn diện đến từ Hàn Quốc, được thiết kế riêng cho chó dưới 1 tuổi. Với thành phần chính là cá hồi giàu Omega-3 và sự kết hợp từ thịt gà, sản phẩm mang đến nguồn năng lượng lành mạnh, hỗ trợ phát triển toàn diện về trí não, thể lực và hệ tiêu hóa cho bé cún.\nLợi ích chính\n\nCông thức đa protein từ cá hồi và thịt gà giúp tăng cường calo và hỗ trợ tăng trưởng nhanh.\nProbiotics và nấm men giúp cân bằng hệ vi sinh đường ruột, h...',55000.00,503,4.10,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',95000.00,62,'all'),(3,1,'Nước sốt pate cho mèo CIAO vị cá ngừ, cá bào nhật &#038; ức gà','Nước sốt pate cho mèo CIAO vị cá ngừ, cá bào nhật &amp; ức gà Tuna, Bonito &amp; Chicken Breast dành cho tất cả các giống mèo.\nThành phần dinh dưỡng\nNước sốt pate cho mèo CIAO vị cá ngừ, cá bào nhật &amp; ức gà bao gồm Katsuo, cá ngừ, dầu đậu nành, chiết xuất Katsuo-bushi, Oligosaccharide, polysaccharide làm dày. Vitamin E, Taurine, chiết xuất trà xanh. Thành phần phân tích đảm bảo chất đạm &gt; 9,0%, chất béo &lt; 0,4% trở lên, chất xơ thô &lt;  0,1%, hàm lượng tro &lt; 2,0%, hàm lượng nước &lt...',35000.00,120,4.40,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',75000.00,299,'all'),(4,1,'Bánh thưởng cho chó BOWWOW Carrot Cheesee Ball','Bánh thưởng cho chó BOWWOW Carrot Cheesee Ball làm từ 100% phô mai nguyên chất và cà rốt, giàu protein và canxi, vitamin A, là món ăn nhẹ bổ dưỡng cho các chú chó, nhất là các chú chó con đang phát triển hệ cơ xương và chó mẹ cần phục hồi thể trạng sau khi sau con. Snack có thể dùng được cho cả chó và mèo.\n\nDành cho mọi giống chó thuộc mọi lứa tuổi, cân nặng\nLà món ăn nhẹ tuyệt vời cho cả chó và mèo\nThành phần: Phô mai, cà rốt, tinh bột bắp, vitamin, khoáng chất\nGiảm tỷ lệ cholesterol xấu trong ...',70000.00,85,3.60,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',130000.00,88,'all'),(5,1,'Snack bánh thưởng cho chó BOWWOW Mixed Sandwich','Snack bánh thưởng cho chó BOWWOW Mixed Sandwich là bánh thưởng đã được các huấn luyện viên sử dụng để huấn luyện chó hiệu quả. Đây cũng là món ăn nhẹ bổ dưỡng cho các chú chó, nhất là chó con và chó mẹ sau khi sinh con cần bổ sung dinh dưỡng bên cạnh các món ăn thường ngày.\n\nDành cho mọi giống chó thuộc mọi lứa tuổi, cân nặng\nGiảm tỷ lệ cholesterol xấu trong huyết thanh, ngăn ngừa béo phì\nThành phần: Gà, cá hồi, rau củ, phô mai, can-xi, rong biển nâu, lúa mì, xơ đậu tương (bánh đậu tương), axit ...',60000.00,260,4.60,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',140000.00,358,'all'),(6,1,'Dụng cụ ăn uống cho chó mèo PAW tự động đa năng','Dụng cụ ăn uống cho chó mèo PAW tự động đa năng là sản phẩm dành cho tất cả giống chó và mèo.\nLợi ích chính\n\nDụng cụ ăn uống cho chó mèo PAW tự động đa năng sang trọng với thiết kế 2 chức năng vô cùng tiện lợi cho thú cưng của bạn dùng để bảo quản thức ăn không bị ỉu hỏng giúp thú cưng ăn ngon miệng hơn\nBình nước uống có thể điều chỉnh cao thấp hợp lý với mọi giống chó mèo\nĐặc biệt chức năng cấp nước uống tự động chảy nước ra khi thú cưng uống hết nhằm đảm bảo giữ vệ sinh sạch sẽ cho nước uống\nB...',430000.00,439,3.90,'active','2026-07-14 11:15:23','2026-07-14 11:15:23',510000.00,40,'all'),(7,1,'Gel vệ s