/*!40000 ALTER TABLE `services` DISABLE KEYS */;
INSERT INTO `services` VALUES (1,2,'Tắm & Sấy khô','Dịch vụ tắm sạch bằng sữa tắm dưỡng lông cao cấp và sấy khô, giúp loại bỏ bụi bẩn và mùi hôi.',50000.00,45,'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?w=400',0.00,'active','all'),(2,2,'Massage chuyên sâu','Massage thư giãn giảm căng thẳng, kích thích tuần hoàn máu và hỗ trợ sức khỏe xương khớp cho thú cưng.',50000.00,30,'https://images.unsplash.com/photo-1544568100-847a948585b9?w=400',0.00,'active','all'),(3,2,'Vệ sinh răng miệng','Chải răng, loại bỏ mảng bám thức ăn và sử dụng xịt thơm miệng chuyên dụng cho thú cưng.',30000.00,20,'https://images.unsplash.com/photo-1583511655857-d19b40a7a54e?w=400',0.00,'active','all'),(4,2,'Cắt & mài móng','Cắt móng an toàn và mài mịn các góc nhọn, tránh cào xước da chủ nuôi và đồ đạc.',30000.00,15,'https://images.unsplash.com/photo-1597633425046-08f5110420b5?w=400',0.00,'active','all'),(5,2,'Chăm sóc bàn chân','Cạo lông kẽ chân, vệ sinh sạch sẽ và thoa kem dưỡng ẩm bảo vệ đệm chân thú cưng.',30000.00,20,'https://images.unsplash.com/photo-1537151608828-ea2b117b62e4?w=400',0.00,'active','all'),(6,2,'Điều trị ký sinh trùng','Tắm thuốc chuyên dụng loại bỏ ve, rận, bọ chét và hướng dẫn phòng ngừa tái nhiễm.',80000.00,30,'https://images.unsplash.com/photo-1548767797-d8c844163c4c?w=400',0.00,'active','all'),(7,2,'Cắt tỉa tạo kiểu','Cắt tỉa và tạo kiểu lông chuyên nghiệp bởi các groomer giàu kinh nghiệm theo yêu cầu.',50000.00,60,'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?w=400',0.00,'active','all'),(8,2,'Nhuộm lông thời trang','Nhuộm màu thời trang cho tai, đuôi hoặc chân bằng màu nhuộm organic an toàn tuyệt đối cho thú cưng.',80000.00,90,'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?w=400',0.00,'active','all'),(9,2,'Vắt tuyến hôi','Vắt tuyến hôi hậu môn giúp làm giảm mùi hôi đặc trưng và ngăn ngừa viêm nhiễm tuyến hôi.',50000.00,15,'https://images.unsplash.com/photo-1533738363-b7f9aef128ce?w=400',0.00,'active','all'),(10,3,'Combo Tắm 11 bước','Quy trình chăm sóc toàn diện 11 bước: 1. Khám da & lông sơ bộ; 2. Chải lông gỡ rối; 3. Cắt & mài móng; 4. Vệ sinh tai; 5. Cạo lông kẽ bàn chân; 6. Vắt tuyến hôi; 7. Tắm lần 1 (sạch sâu); 8. Tắm lần 2 (dưỡng mượt); 9. Massage nhẹ nhàng; 10. Sấy khô & chải phồng; 11. Xịt dưỡng bóng lông & nước hoa.',150000.00,90,'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?w=400',0.00,'active','all'),(11,3,'Combo Tắm cơ bản & cắt tỉa lông','Gói combo tiết kiệm bao gồm dịch vụ tắm sấy thơm tho kết hợp cắt tỉa tạo kiểu gọn gàng cho thú cưng.',100000.00,75,'https://images.unsplash.com/photo-1516734212186-a967f81ad0d7?w=400',0.00,'active','all'),(12,3,'Combo Chăm sóc & bảo vệ móng','Gói chăm sóc móng chuyên biệt: cắt móng, mài mịn, vệ sinh sạch đệm chân và thoa dầu dưỡng đệm chân cao cấp.',80000.00,30,'https://images.unsplash.com/photo-1597633425046-08f5110420b5?w=400',0.00,'active','all'),(13,1,'Khám & Điều trị','Khám lâm sàng tổng quát bởi bác sĩ thú y để chẩn đoán tình trạng sức khỏe và đưa ra phác đồ điều trị.',30000.00,30,'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=400',0.00,'active','all'),(14,1,'Xét nghiệm','Xét nghiệm máu, xét nghiệm phân, hoặc soi kính hiển vi để phát hiện ký sinh trùng, virus và các bệnh lý.',50000.00,40,'https://images.unsplash.com/photo-1579154204601-01588f35116f?w=400',0.00,'active','all'),(15,1,'Siêu âm','Siêu âm ổ bụng, siêu âm thai để kiểm tra tình trạng nội tạng, phát hiện khối u hoặc theo dõi thai kỳ.',100000.00,25,'https://images.unsplash.com/photo-1579684389782-64d84b5e901a?w=400',0.00,'active','all'),(16,1,'Tiêm phòng','Tiêm vaccine phòng các bệnh truyền nhiễm nguy hiểm (dại, 5 bệnh, 7 bệnh) kèm sổ theo dõi sức khỏe.',100000.00,15,'https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=400',0.00,'active','all'),(17,1,'Phẫu thuật','Phẫu thuật ngoại khoa vô trùng: triệt sản, mổ đẻ, khâu vết thương sâu, phẫu thuật xương khớp.',200000.00,120,'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=400',0.00,'active','all'),(18,1,'Cấp cứu 24/7','Dịch vụ xử lý cấp cứu khẩn cấp 24/7 đối với các trường hợp tai nạn, ngộ độc, khó đẻ hoặc suy hô hấp.',150000.00,60,'https://images.unsplash.com/photo-1584132967334-10e028bd69f7?w=400',0.00,'active','all');
