  `branch_id` bigint NOT NULL,
  `slot_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `max_booking` int NOT NULL DEFAULT '1',
  `booked_count` int NOT NULL DEFAULT '0',
  `status` enum('available','full','locked','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'available',
  `slot_type` enum('exam','grooming') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'exam',
  PRIMARY KEY (`slot_id`),
  KEY `idx_time_slots_doctor_id` (`doctor_id`),
  KEY `idx_time_slots_branch_id` (`branch_id`),
  KEY `idx_time_slots_type_branch_date` (`slot_type`,`branch_id`,`slot_date`),
  CONSTRAINT `time_slots_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`branch_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `time_slots_doctor_id_fkey` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`doctor_id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9841 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
